  llm_response: null,
  service_response: null,
  provider: 'openai',
  model: 'gpt-4o-mini',
  mode: 'image',
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

if (statusCode >= 400 || input.error) {
  const errorMessage = input.error?.message || input.message || 'OpenAI API error';
  _trace.llm_response = `Error: ${errorMessage}`;
  _trace.service_response = input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    success: false,
    error: {
      code: 'VISION_API_ERROR',
      message: errorMessage,
      http_status: statusCode >= 400 ? statusCode : 500
    },
    _trace: _trace,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

try {
  const content = input.choices?.[0]?.message?.content || '{}';
  const usage = input.usage || {};
  const detection = JSON.parse(content);

  _trace.llm_response = content;
  _trace.service_response = input;
