// ============================================
// NORMALIZE IMAGE RESPONSE
// RFC-014: _trace with llm_response
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const statusCode = input.statusCode || 200;

// Context fields
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Initialize trace
const _trace = {
  llm_response: null,
  service_response: null,
  provider: 'openai',
  model: 'gpt-4o-mini',
  mode: 'image',
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

if (statusCode >= 400 || input.error) {
  const errorMessage = input.error?.message || input.message || 'OpenAI API error';
  _trace.llm_response = `Error: ${errorMessage}`;
  _trace.service_response = input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    success: false,
    error: {
      code: 'VISION_API_ERROR',
      message: errorMessage,
      http_status: statusCode >= 400 ? statusCode : 500
    },
    _trace: _trace,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

try {
  const content = input.choices?.[0]?.message?.content || '{}';
  const usage = input.usage || {};
  const detection = JSON.parse(content);

  _trace.llm_response = content;
  _trace.service_response = input;
  _trace.tokens = {
    input: usage.prompt_tokens || 0,
    output: usage.completion_tokens || 0
  };
  _trace.latency_ms = Date.now() - startTime;

  const primaryScript = detection.primary_script || 'unknown';
  const scripts = detection.scripts || [{ script: primaryScript, confidence: 0.5, percentage: 100 }];
  const isRtl = detection.is_rtl || ['hebrew', 'arabic', 'persian', 'urdu'].includes(primaryScript);

  const providerMap = {
    'hebrew': ['mistral', 'google_vision', 'tesseract'],
    'arabic': ['google_vision', 'azure', 'mistral'],
    'han': ['google_vision', 'azure', 'mistral'],
    'latin': ['mistral', 'google_vision', 'tesseract'],
    'cyrillic': ['google_vision', 'mistral', 'tesseract']
  };

  const recommendedProviders = detection.recommended_providers || providerMap[primaryScript] || ['mistral', 'google_vision', 'tesseract'];

  return {
    success: true,
    data: {
      primary_script: primaryScript,
      scripts: scripts,
      is_rtl: isRtl,
      has_diacritics: detection.has_diacritics || false,
      recommended_providers: recommendedProviders,
      sample_text: detection.sample_text || null
    },
    _trace: _trace,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
} catch (e) {
  _trace.llm_response = `Parse error: ${e.message}`;
  _trace.latency_ms = Date.now() - startTime;

  return {
    success: false,
    error: { code: 'PARSE_ERROR', message: e.message, http_status: 500 },
    _trace: _trace,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

